{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Weights the contribution of model-based and model-free values for stage 1 choices.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "stage_1_stickiness",
      "title": "Stage 1 Choice Stickiness",
      "description": "Adds a bonus to the stage 1 logits for the action chosen in the previous trial.",
      "params": [
        {
          "name": "stickiness_1",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "stick_vector_1 = np.zeros(2)\n        if last_action_1 != -1:\n            stick_vector_1[last_action_1] = 1.0\n            \n        bias_vector_1 = np.array([bias_1, 0.0])\n            \n        logits_1 = beta * q_net + stickiness_1 * stick_vector_1 + bias_vector_1",
      "expressible_in_slots": true
    },
    {
      "name": "stage_2_stickiness",
      "title": "Stage 2 Choice Stickiness",
      "description": "Adds a bonus to the stage 2 logits for the action previously chosen in the current second-stage state.",
      "params": [
        {
          "name": "stickiness_2",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "stick_vector_2 = np.zeros(2)\n        if last_action_2[state_idx] != -1:\n            stick_vector_2[last_action_2[state_idx]] = 1.0\n            \n        logits_2 = beta * q_stage2_mf[state_idx] + stickiness_2 * stick_vector_2",
      "expressible_in_slots": true
    },
    {
      "name": "value_decay",
      "title": "Value Decay",
      "description": "Decays the Q-values of unchosen actions towards 0.5 at the end of each trial.",
      "params": [
        {
          "name": "decay_rate",
          "bounds": [0, 1]
        }
      ],
      "evidence": "unchosen_action_1 = 1 - action_1[trial]\n        q_stage1_mf[unchosen_action_1] += decay_rate * (0.5 - q_stage1_mf[unchosen_action_1])\n        \n        for s in range(2):\n            for a in range(2):\n                if not (s == state_idx and a == action_2[trial]):\n                    q_stage2_mf[s, a] += decay_rate * (0.5 - q_stage2_mf[s, a])",
      "expressible_in_slots": true
    },
    {
      "name": "stage_1_bias",
      "title": "Stage 1 Bias",
      "description": "Adds a constant bias to the logit of choosing spaceship 0 at stage 1.",
      "params": [
        {
          "name": "bias_1",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "bias_vector_1 = np.array([bias_1, 0.0])\n            \n        logits_1 = beta * q_net + stickiness_1 * stick_vector_1 + bias_vector_1",
      "expressible_in_slots": true
    }
  ]
}
